<template><BioNexusDialog ref="box" size="compact" kicker="Confirmación" :title="title"><section class="confirm-body"><p>{{ message }}</p><strong>{{ label }}</strong><BioNexusCheckbox v-if="showInactiveOption" v-model="includeInactive" label="Incluir exámenes inactivos" help="Los exámenes inactivos también se agregarán a la lista de trabajo." /></section><template #footer><button type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="cancel">Cancelar</button><button type="button" class="bio-nexus-action bio-nexus-action-primary" @click="accept">Sí, agregar</button></template></BioNexusDialog></template>
<script setup>import{ref}from"vue";import BioNexusCheckbox from"@/components/ui/BioNexusCheckbox.vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";const emit=defineEmits(["confirm"]),box=ref(null),title=ref(""),message=ref(""),label=ref(""),showInactiveOption=ref(false),includeInactive=ref(false);function open(options){title.value=options?.title||"Confirmar";message.value=options?.message||"";label.value=options?.label||"";showInactiveOption.value=Boolean(options?.showInactiveOption);includeInactive.value=false;box.value?.open()}function accept(){box.value?.close();emit("confirm",{includeInactive:includeInactive.value})}function cancel(){box.value?.close()}defineExpose({open});</script>
<style scoped>.confirm-body{display:grid;gap:12px;padding:8px 2px}.confirm-body p{margin:0;color:var(--bio-nexus-color-text-secondary);line-height:1.5}.confirm-body strong{color:var(--bio-nexus-color-primary-strong)}</style>
